import { ZodError } from 'zod';
import { HttpError } from '../utils/errors.js';

export function notFound(req, res) {
  res.status(404).json({ error: `Not found: ${req.method} ${req.path}` });
}

// Central error handler. Messages are generated by us, never by echoing request config,
// so cURL secrets (cookies / tokens) cannot leak into responses or logs.
export function errorHandler(err, req, res, _next) {
  if (err instanceof ZodError) {
    const details = err.issues.map((i) => `${i.path.join('.') || 'body'}: ${i.message}`);
    return res.status(400).json({ error: 'Invalid input', details });
  }
  const status = err instanceof HttpError ? err.status : err.type === 'entity.parse.failed' ? 400 : 500;
  if (status === 500) console.error('Unhandled error:', err.message);
  res.status(status).json({ error: status === 500 ? 'Internal server error' : err.message });
}
